draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two stick figures
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 120);
  ctx.lineTo(W/4 - 20, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 120);
  ctx.lineTo(W/4 + 20, H/2 + 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 120);
  ctx.lineTo(W - W/4 - 20, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 120);
  ctx.lineTo(W - W/4 + 20, H/2 + 100);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/4 + 20 + Math.sin(t) * 10, H/2 + 50);
  ctx.lineTo(W - W/4 - 20 + Math.cos(t) * 10, H/2 + 50);
  ctx.stroke();

  ctx.restore();
}
